module tb;
  typedef struct { int a; string s; } rec_t;
  int qq[$][$];
  int q[$];
  string ss[$][$];
  real rr[$][$];
  rec_t rq[$][$];
  rec_t r;
  string aq[int][$];
  string bq[$][$:1];
  int dq[][$];
  real rt[$];
  int t[$];
  initial begin
    qq.push_back({});
    qq[0].push_back(1);
    qq[0][1] = 5;
    $display("at size: %p size %0d", qq[0], qq[0].size());
    qq[0][3] = 9;
    $display("past end: %p size %0d", qq[0], qq[0].size());
    q.push_back(1);
    q[1] = 5;
    q[3] = 9;
    $display("plain: %p", q);
    ss.push_back({});
    ss[0].push_back("a");
    ss[0][1] = "b";
    ss[0][3] = "d";
    $display("strings: %p size %0d", ss[0], ss[0].size());
    rr.push_back({});
    rr[0].push_back(1.5);
    rr[0][1] = 2.5;
    rr[0][3] = 4.5;
    rt = rr[0];
    $display("reals: size %0d %0.1f", rr[0].size(), rt[1]);
    rq.push_back({});
    r.a = 1; r.s = "x";
    rq[0].push_back(r);
    r.a = 2; r.s = "y";
    rq[0][1] = r;
    rq[0][3] = r;
    $display("records: size %0d %0d %s", rq[0].size(), rq[0][1].a, rq[0][1].s);
    t.push_back(7);
    qq[1] = t;
    qq[1][1] = 8;
    $display("whole element: size %0d %p", qq.size(), qq[1]);
    aq[5].push_back("a");
    aq[5][1] = "b";
    aq[5][3] = "d";
    $display("keyed: size %0d", aq[5].size());
    bq.push_back({});
    bq[0][0] = "a";
    bq[0][1] = "b";
    bq[0][2] = "c";
    $display("bounded: size %0d", bq[0].size());
    dq = new[1];
    dq[0][0] = 1;
    dq[0][1] = 2;
    $display("dynamic: size %0d %p", dq.size(), dq[0]);
    $display("done");
    $finish;
  end
endmodule
